package orchestrator.api

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.nio.file.{Files, Path, Paths, LinkOption}
import java.io.File
import scala.collection.JavaConverters._

object ContainerConfig {
  val WORKSPACE_ROOT: Path = Paths.get("/var/lib/orchestrator/workspaces")
  val ALLOWED_EXTENSIONS: Set[String] = Set(".yaml", ".yml", ".json", ".toml")
  val MAX_DEPTH: Int = 3
}

case class FileEntry(name: String, isDirectory: Boolean, size: Long)
case class ListingResponse(path: String, entries: List[FileEntry], truncated: Boolean)

trait PathValidator {
  def validatePath(requestedPath: String): Either[String, Path] = {
    val cleaned = requestedPath.replaceAll("\\.\\.", "").replaceAll("//+", "/")
    val resolved = ContainerConfig.WORKSPACE_ROOT.resolve(cleaned)
    val normalized = resolved.normalize()

    if (!normalized.startsWith(ContainerConfig.WORKSPACE_ROOT)) {
      Left(s"Access denied: path escapes workspace root")
    } else {
      Right(normalized)
    }
  }
}

trait SymlinkResolver {
  def resolveSymlinks(path: Path): Future[Path] = Future {
    if (Files.isSymbolicLink(path)) {
      val target = Files.readSymbolicLink(path)
      if (target.isAbsolute) target
      else path.getParent.resolve(target).normalize()
    } else {
      path.toRealPath(LinkOption.NOFOLLOW_LINKS)
    }
  }
}

class WorkspaceListingService extends PathValidator with SymlinkResolver {

  private def checkDepth(path: Path): Boolean = {
    val relative = ContainerConfig.WORKSPACE_ROOT.relativize(path)
    relative.getNameCount <= ContainerConfig.MAX_DEPTH
  }

  private def filterEntries(entries: List[Path]): List[Path] = {
    entries.filter { entry =>
      val name = entry.getFileName.toString
      !name.startsWith(".") && !name.startsWith("__")
    }
  }

  private def buildEntry(path: Path): Future[FileEntry] = Future {
    FileEntry(
      name = path.getFileName.toString,
      isDirectory = Files.isDirectory(path),
      size = if (Files.isRegularFile(path)) Files.size(path) else 0L
    )
  }

  def listWorkspace(workspaceId: String, subPath: String): Future[Either[String, ListingResponse]] = {
    val requestedPath = s"$workspaceId/$subPath"

    validatePath(requestedPath) match {
      case Left(err) => Future.successful(Left(err))
      case Right(validatedPath) =>
        resolveSymlinks(validatedPath).flatMap { resolvedPath =>
          Future {
            if (!Files.exists(resolvedPath)) {
              Left("Path not found")
            } else if (!Files.isDirectory(resolvedPath)) {
              Left("Path is not a directory")
            } else if (!checkDepth(resolvedPath)) {
              Left("Maximum directory depth exceeded")
            } else {
              val stream = Files.list(resolvedPath)
              try {
                val allEntries = stream.iterator().asScala.toList
                val filtered = filterEntries(allEntries)
                val truncated = filtered.size > 100
                val limited = filtered.take(100)
                Right((limited, truncated, resolvedPath))
              } finally {
                stream.close()
              }
            }
          }.flatMap {
            case Left(err) => Future.successful(Left(err))
            case Right((paths, truncated, resolved)) =>
              Future.sequence(paths.map(buildEntry)).map { entries =>
                Right(ListingResponse(
                  path = ContainerConfig.WORKSPACE_ROOT.relativize(resolved).toString,
                  entries = entries,
                  truncated = truncated
                ))
              }
          }
        }
    }
  }
}

class ContainerOrchestrator {
  private val listingService = new WorkspaceListingService()

  def handleListRequest(workspaceId: String, path: String): Future[Either[String, ListingResponse]] = {
    if (workspaceId.isEmpty || workspaceId.contains("/")) {
      Future.successful(Left("Invalid workspace ID"))
    } else {
      listingService.listWorkspace(workspaceId, path)
    }
  }
}
